    public static class HookStates
    {
        public const int Count = 5;

        public const uint Idle = 0u;
        public const uint Armed = 1u;
        public const uint Running = 2u;
        public const uint Detached = 3u;
        public const uint Error = 0xFu;

        public static readonly (uint Value, string Name)[] Names =
        [
            (Idle, "IDLE"),
            (Armed, "ARMED"),
            (Running, "RUNNING"),
            (Detached, "DETACHED"),
            (Error, "ERROR"),
        ];

        public static string Text(uint state) => state switch
        {
            Idle => "IDLE",
            Armed => "ARMED",
            Running => "RUNNING",
            Detached => "DETACHED",
            Error => "ERROR",
            _ => "?(" + state.ToString(System.Globalization.CultureInfo.InvariantCulture) + ")",
        };
    }

